package net.minecraft.client.model.geom;import java.util.*;public class EntityModelSet{public Map<Object,Object> roots=new HashMap<>();public int bakes,emfRejected;public Map<ModelLayerLocation,Integer> attempts=new HashMap<>();public ModelPart bakeLayer(ModelLayerLocation layer){bakes++;Integer previous=attempts.put(layer,attempts.getOrDefault(layer,0)+1);if(previous!=null&&previous>64)emfRejected++;Map<String,ModelPart> children=new HashMap<>();for(String name:new String[]{"Head","Body","LeftArm","RightArm","LeftLeg","RightLeg"}){ModelPart p=new ModelPart(List.of(),Map.of());p.marker=name;children.put(name,p);}return new ModelPart(List.of(),children);}public void reload(){roots=new HashMap<>();attempts.clear();}}
